<div class="container"><div class="breadcrumbs"><a href="<?= e(url('/shop.php')) ?>">The flower shop</a><span>/</span><?= e($product['name']) ?></div><section class="product-detail"><img class="product-detail-image" src="<?= e(url('/' . $product['image_path'])) ?>" alt="<?= e($product['name']) ?> flower arrangement" width="800" height="850"><div class="product-detail-copy"><p class="eyebrow"><?= e($product['category_name']) ?></p><h1><?= e($product['name']) ?></h1><p class="product-price"><?= e(format_money($product['price'])) ?></p><p class="product-description"><?= nl2br(e($product['description'])) ?></p><p class="stock-label"><?= (int) $product['stock_quantity'] > 0 ? e($product['stock_quantity']) . ' available · Ready for a little joy' : 'Sold out · More lovely blooms soon' ?></p>
